{"content":"/**
 * Glob patterns compiled to path matchers: wildcards that stop at `/`,
 * whole-segment globstars, POSIX-style character classes, backslash escapes and
 * the leading-dot rule.
 */

/** Failure raised while compiling a pattern. */
export class GlobError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [index] 0-based index into the pattern where the fault starts
   */
  constructor(message, index) {
    super(message);
    this.name = 'GlobError';
    this.index = index;
  }
}

/** Characters that are special inside a regex character class `[...]`. */
const CLASS_SPECIAL = /[[\]\\^-]/;
const ANY_CLASS_SPECIAL = /[[\]\\^-]/;

/**
 * Escape a literal character for use as a regex atom (outside a class).
 */
function esc(ch) {
  return /[\\^$.|?*+()[]{}]/.test(ch) ? '\\' + ch : ch;
}

/**
 * Escape a literal character for use inside a regex character class `[...]`.
 */
function escClass(ch) {
  return CLASS_SPECIAL.test(ch) ? '\\' + ch : ch;
}

/** @returns true for ASCII letters */
function isAlpha(ch) {
  const c = ch.charCodeAt(0);
  return (c >= 65 && c <= 90) || (c >= 97 && c <= 122);
}

/** @returns the upper-case form of an ASCII letter, else the char unchanged */
function upper(ch) {
  const c = ch.charCodeAt(0);
  return c >= 97 && c <= 122 ? String.fromCharCode(c - 32) : ch;
}

/** @returns the lower-case form of an ASCII letter, else the char unchanged */
function lower(ch) {
  const c = ch.charCodeAt(0);
  return c >= 65 && c <= 90 ? String.fromCharCode(c + 32) : ch;
}

/**
 * Wrap an ASCII letter as a case-insensitive regex atom `[Aa]`.
 */
function caseFoldLetter(ch) {
  const u = upper(ch);
  const l = lower(ch);
  if (u !== l) return '[' + u + l + ']';
  return esc(ch);
}

/**
 * Split `pattern` into the raw text of each `/`-separated segment. The
 * splitter is only aware of `\` (which protects the next char from being
 * treated as a separator or bracket) and `[...]` (which protects `/` from
 * being a separator and reports a `/` inside it as an error). Backslashes and
 * brackets are preserved verbatim in the emitted text so the segment parser can
 * interpret them.
 *
 * Each returned object carries `text` (the raw segment) and `start` (the
 * 0-based pattern index where the segment begins). A trailing backslash
 * anywhere in the pattern is reported with its own index.
 *
 * @param {string} pattern
 * @returns {Array<{text: string, start: number}>}
 */
function splitSegments(pattern) {
  const out = [];
  let text = '';
  let start = 0;
  let i = 0;
  const n = pattern.length;
  while (i < n) {
    const ch = pattern[i];
    if (ch === '\\') {
      if (i + 1 >= n) {
        throw new GlobError('trailing backslash', i);
      }
      // Keep the backslash and the escaped char verbatim.
      text += '\\' + pattern[i + 1];
      i += 2;
      continue;
    }
    if (ch === '[' ) {
      const open = i;
      text += ch;
      i += 1;
      let first = true;
      let closed = false;
      while (i < n) {
        const c = pattern[i];
        if (c === '\\') {
          if (i + 1 >= n) {
            throw new GlobError('trailing backslash', i);
          }
          text += '\\' + pattern[i + 1];
          i += 2;
          first = false;
          continue;
        }
        if (c === '/' ) {
          throw new GlobError('path separator in character class', open);
        }
        text += c;
        if (c === ']' && !first) {
          closed = true;
          i += 1;
          break;
        }
        i += 1;
        first = false;
      }
      if (!closed) {
        throw new GlobError('unterminated character class', open);
      }
      continue;
    }
    if (ch === '/' ) {
      out.push({ text, start });
      text = '';
      start = i + 1;
      i += 1;
      continue;
    }
    text += ch;
    i += 1;
  }
  out.push({ text, start });
  return out;
}

/**
 * Parse one segment's raw text (escapes and brackets intact) into a regex atom
 * plus metadata. `dot` is true when the segment begins with a literal `.` —
 * either an unescaped `.` or `\.` — meaning it may match a path segment that
 * begins with `.`.
 *
 * @param {string} text raw segment text
 * @param {boolean} nocase
 * @returns {{ body: string, dot: boolean }} `body` matches a single segment.
 */
function parseSegment(text, nocase) {
  let body = '';
  let dot = false;
  let leading = true;
  let i = 0;
  const n = text.length;
  while (i < n) {
    const ch = text[i];
    if (ch === '\\') {
      // Escaped character: literal value of the next char.
      const next = text[i + 1];
      if (next === '.') {
        if (leading) dot = true;
        body += '\\.';
      } else if (isAlpha(next)) {
        body += nocase ? caseFoldLetter(next) : esc(next);
      } else {
        body += esc(next);
      }
      i += 2;
      leading = false;
      continue;
    }
    if (ch === '*') {
      while (i < n && text[i] === '*') i += 1;
      body += '[^/]*';
      leading = false;
      continue;
    }
    if (ch === '?') {
      body += '[^/]';
      i += 1;
      leading = false;
      continue;
    }
    if (ch === '[') {
      const result = parseClass(text, i, nocase);
      body += result.body;
      i = result.next;
      leading = false;
      continue;
    }
    if (ch === '.') {
      if (leading) dot = true;
      body += '\\.';
    } else if (isAlpha(ch)) {
      body += nocase ? caseFoldLetter(ch) : esc(ch);
    } else {
      body += esc(ch);
    }
    i += 1;
    leading = false;
  }
  return { body, dot };
}

/**
 * Parse a character class `[...]` beginning at index `i` (the `[`). Returns the
 * regex atom (matching exactly one character) and the index past the closing
 * `]`.
 *
 * - `[!...]` / `[^...]` negate and match one char that is neither `/` nor
 *   listed.
 * - A `]` immediately after the opening bracket (or the negation mark) is a
 *   literal member.
 * - A `-` at either end of the list is a literal `-`; elsewhere between two
 *   ASCII letters it denotes a range.
 * - `\` escapes the next character inside the class.
 *
 * @param {string} text
 * @param {number} i index of `[`
 * @param {boolean} nocase
 * @returns {{ body: string, next: number }}
 */
function parseClass(text, i, nocase) {
  const n = text.length;
  const start = i;
  i += 1; // consume `[`
  let negated = false;
  if (i < n && (text[i] === '!' || text[i] === '^')) {
    negated = true;
    i += 1;
  }
  let inner = '';
  let first = true;
  let closed = false;
  while (i < n) {
    const ch = text[i];
    if (ch === '\\') {
      if (i + 1 >= n) {
        throw new GlobError('trailing backslash', start);
      }
      inner += escClass(text[i + 1]);
      i += 2;
      first = false;
      continue;
    }
    if (ch === ']' && !first) {
      closed = true;
      i += 1;
      break;
    }
    if (ch === ']' && first) {
      // Literal `]` as the first member of the list.
      inner += '\\]';
      i += 1;
      first = false;
      continue;
    }
    if (ch === '-' ) {
      const next = i + 1 < n ? text[i + 1] : '';
      // A `-` at the very start (just after `[` or the negation mark) or at the
      // very end (followed by `]`) is a literal dash.
      if (first || next === '' || next === ']' ) {
        inner += escClass('-');
        i += 1;
        first = false;
        continue;
      }
      const prev = text[i - 1];
      if (isAlpha(prev) && isAlpha(next)) {
        inner += rangeClass(prev, next, nocase);
        i += 2;
        first = false;
        continue;
      }
      inner += escClass('-');
      i += 1;
      first = false;
      continue;
    }
    if (ch === '/' ) {
      throw new GlobError('path separator in character class', start);
    }
    inner += escClass(ch);
    i += 1;
    first = false;
  }
  if (!closed) {
    throw new GlobError('unterminated character class', start);
  }
  // A glob bracket expression matches exactly one character. `[!...]`/`[^...]`
  // match one character that is neither `/` nor listed (the `/` exclusion is
  // harmless within a single path segment).
  return { body: negated ? '[^/' + inner + ']' : '[' + inner + ']', next: i };
}

/**
 * Build the (possibly empty) contents of a regex class for a glob range
 * `lo`-`hi`, expanding to cover both cases when `nocase`.
 *
 * @param {string} lo
 * @param {string} hi
 * @param {boolean} nocase
 */
function rangeClass(lo, hi, nocase) {
  let text = escClass(lo) + '-' + escClass(hi);
  if (nocase && (isAlpha(lo) || isAlpha(hi))) {
    text += escClass(upper(lo)) + '-' + escClass(upper(hi));
    text += escClass(lower(lo)) + '-' + escClass(lower(hi));
  }
  return text;
}

/**
 * Compile a glob pattern into an ordered list of segment matchers.
 *
 * @param {string} pattern
 * @param {boolean} nocase
 * @returns {Array<{regex: RegExp|null, dot: boolean, globstar: boolean}>}
 */
function compilePattern(pattern, nocase) {
  const raw = splitSegments(pattern);
  const segs = [];
  for (const { text } of raw) {
    if (text.length === 2 && text[0] === '*' && text[1] === '*') {
      // A whole segment that is exactly `**` is the globstar.
      segs.push({ regex: null, dot: false, globstar: true });
      continue;
    }
    const parsed = parseSegment(text, nocase);
    segs.push({ regex: new RegExp('^(?:' + parsed.body + ')$'), dot: parsed.dot, globstar: false });
  }
  // Collapse adjacent globstars (`**/**` -> `**`).
  const collapsed = [];
  for (const s of segs) {
    if (s.globstar && collapsed.length > 0 && collapsed[collapsed.length - 1].globstar) {
      continue;
    }
    collapsed.push(s);
  }
  return collapsed;
}

/**
 * Compile a glob `pattern` into a matcher.
 *
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options] leading-dot and case policy
 * @returns {(path: string) => boolean} matcher for whole paths
 */
export function compile(pattern, options = {}) {
  if (typeof pattern !== 'string') {
    throw new GlobError('pattern must be a string');
  }
  if (pattern.length === 0) {
    throw new GlobError('pattern must not be empty');
  }
  const nocase = !!options.nocase;
  const segs = compilePattern(pattern, nocase);
  const dotAllowed = !!options.dot;
  return makeMatcher(segs, dotAllowed);
}

/**
 * One-shot matcher.
 *
 * @param {string} path path to test
 * @param {string} pattern glob pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options]
 * @returns {boolean}
 */
export function isMatch(path, pattern, options = {}) {
  const matcher = compile(pattern, options);
  return matcher(path);
}

/**
 * Keep the matching paths in their original order, preserving duplicates.
 *
 * @param {string[]} paths
 * @param {string} pattern
 * @param {{ dot?: boolean, nocase?: boolean }} [options]
 * @returns {string[]}
 */
export function filter(paths, pattern, options = {}) {
  if (!Array.isArray(paths)) {
    throw new GlobError('paths must be an array');
  }
  const matcher = compile(pattern, options);
  const result = [];
  for (const p of paths) {
    if (matcher(p)) result.push(p);
  }
  return result;
}

/**
 * Build a matcher function from compiled segments.
 *
 * @param {Array<{regex: RegExp|null, dot: boolean, globstar: boolean}>} segs
 * @param {boolean} dotAllowed whether the leading-dot rule is disabled globally
 * @returns {(path: string) => boolean}
 */
function makeMatcher(segs, dotAllowed) {
  /**
   * @param {string[]} pathSegs
   * @param {number} si pattern segment index
   * @returns {boolean}
   */
  function rec(pathSegs, si) {
    if (si >= segs.length) return pathSegs.length === 0;
    const seg = segs[si];
    if (seg.globstar) {
      // Consume zero or more whole path segments. When the dot rule is in
      // effect, a globstar may not span a segment beginning with `.` unless
      // `dotAllowed`.
      for (let k = 0; k <= pathSegs.length; k += 1) {
