import('./src/glob.js').then(m => {
  const checks = [
    // dot rule edge cases
    ['[.]x', '.x', false, {}],        // bracket expr refuses leading dot
    ['[.]x', '.x', false, {}],        
    ['.*', '.x', true, {}],
    ['\\\\.*', '.x', true, {}],
    ['**', '.x', false, {}],
    ['**/y', '.x/y', false, {}],
    ['**/y', '.x/y', true, {dot:true}],
    ['a/*', 'a/.b', false, {}],
    ['a/*', 'a/.b', true, {dot:true}],
    ['*', '.x', false, {}],
    ['?x', '.x', false, {}],
    // dot with dot:true for leading dot in path via *
    ['*', '.x', true, {dot:true}],
    // case folding
    ['A.JS', '*.js', false, {}],
    ['A.JS', '*.js', true, {nocase:true}],
    ['SRC/A.JS', 'src/**/[a-z].js', true, {nocase:true}],
    // errors
    ['a[bc', /unterminated/, 1],
    ['\\\\', /trailing/, 1],
    ['', /empty/],
    [null, /string/],
  ];
  for (const [p, pathOrRe, exp, opts] of checks) {
    let got;
    try {
      if (exp === '/string/' || typeof exp === 'boolean') {
        got = m.isMatch(pathOrRe, p, opts);
      }
    } catch(e){ got = e; }
    // just sanity-print
  }
  // direct error checks
  const err = (() => { try { m.compile('a[bc'); } catch(e){ return e; } })();
  console.log('unterminated idx:', err.index, err.message);
  const e2 = (() => { try { m.compile('a\\\\'); } catch(e){ return e; } })();
  console.log('trailing idx:', e2.index, e2.message);
  const e3 = (() => { try { m.compile(''); } catch(e){ return e; } })();
  console.log('empty:', e3.message, e3.index);
  const e4 = (() => { try { m.isMatch(7, '*'); } catch(e){ return e; } })();
  console.log('nonstring path:', e4.message);
});
"","description":"Manual edge-case verification"}

